#include "assets/AssetPackage.h"
#include <algorithm>
namespace Paladin {
AssetBytes AssetPackage::write(std::vector<AssetEntry> entries){std::sort(entries.begin(),entries.end(),[](auto& a,auto& b){return a.record.name<b.record.name;});AssetWriter table,payload;std::map<AssetId,std::string> ids;for(auto& e:entries){auto& r=e.record;if(r.id!=assetId(r.name)||!ids.emplace(r.id,r.name).second)throw std::runtime_error("Duplicate AssetId/hash collision: "+r.name);table.u64(r.id);table.u32(unsigned(r.type));table.u32(r.flags);table.u32(r.schema);table.u64(payload.bytes.size());table.u64(e.data.size());table.u64(e.data.size());table.text(r.name);table.u32(unsigned(r.dependencies.size()));for(auto d:r.dependencies)table.u64(d);payload.raw(e.data);}AssetWriter body;body.raw(table.bytes);body.raw(payload.bytes);AssetWriter w;for(char c:std::string("PALPAK01"))w.u8(c);w.u32(AssetFormatVersion);w.u32(AssetCompilerVersion);w.u32(0x01020304);w.u32(AssetSchemaVersion);w.u32(unsigned(entries.size()));w.u64(table.bytes.size());w.u64(body.bytes.size());for(char c:assetDigest(body.bytes))w.u8(c);w.raw(body.bytes);return w.bytes;}
std::shared_ptr<AssetPackage> AssetPackage::read(const std::filesystem::path& p){auto out=std::make_shared<AssetPackage>();out->path=p;out->bytes_=readAssetFile(p);AssetReader r{out->bytes_};auto magic=r.take(8);if(std::string(magic.begin(),magic.end())!="PALPAK01")throw std::runtime_error("Invalid PALPAK magic");if(r.u32()!=AssetFormatVersion)throw std::runtime_error("Unsupported package version");if(r.u32()!=AssetCompilerVersion)throw std::runtime_error("Unsupported compiler version");if(r.u32()!=0x01020304||r.u32()!=AssetSchemaVersion)throw std::runtime_error("Unsupported package endian/schema");auto count=r.u32();auto tables=r.u64(),size=r.u64();auto hash=r.take(64);out->identity=std::string(hash.begin(),hash.end());const auto header=r.pos;if(count>1000000||size!=r.bytes.size()-header||tables>size||assetDigest(r.bytes.subspan(header))!=out->identity)throw std::runtime_error("Corrupt package size/integrity");AssetReader t{r.bytes.subspan(header,size_t(tables))};std::uint64_t end=0;for(unsigned i=0;i<count;++i){AssetRecord a;a.id=t.u64();a.type=AssetType(t.u32());a.flags=t.u32();a.schema=t.u32();a.offset=t.u64();a.compressedSize=t.u64();a.uncompressedSize=t.u64();a.name=t.text();auto n=t.u32();if(n>count+100000||n>(t.bytes.size()-t.pos)/8)throw std::runtime_error("Invalid dependency count");for(unsigned j=0;j<n;++j)a.dependencies.push_back(t.u64());if(a.schema!=AssetSchemaVersion||a.flags||unsigned(a.type)<1||unsigned(a.type)>unsigned(AssetType::GenericData)||a.compressedSize!=a.uncompressedSize||a.offset<end||a.offset>size-tables||a.uncompressedSize>size-tables-a.offset||a.id!=assetId(a.name))throw std::runtime_error("Invalid asset record offsets/schema: "+a.name);end=a.offset+a.uncompressedSize;a.offset+=header+tables;if(!out->records_.emplace(a.id,a).second)throw std::runtime_error("Duplicate package AssetId");}t.end();return out;}
}
